import{_ as s,o as t,c as a,ag as l}from"./chunks/framework.DaCm-iTo.js";const k=JSON.parse('{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/commands.md","filePath":"en/modules/skills/commands.md","lastUpdated":null}'),d={name:"en/modules/skills/commands.md"};function i(o,e,n,r,c,p){return t(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to &quot;Commands and Permissions&quot;">​</a></h1><p>The main command of EmakiSkills is <code>/emakiskills</code>, with <code>/eskills</code> as an alias. Commands are used to open the skill GUI, toggle cast mode, upgrade skills, manage skill levels, clear slots, inspect profiles, resync skill sources, and reload configuration.</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/eskills help</code></td><td>none</td><td>Print the command help list. Also shown when running <code>/eskills</code> with no arguments.</td></tr><tr><td><code>/eskills gui</code></td><td><code>emakiskills.use</code></td><td>Open the skill GUI.</td></tr><tr><td>\`/eskills castmode &lt;on</td><td>off</td><td>toggle&gt;\`</td></tr><tr><td><code>/eskills upgrade &lt;skill&gt;</code></td><td><code>emakiskills.use</code></td><td>Try to upgrade a skill.</td></tr><tr><td><code>/eskills level get &lt;player&gt; &lt;skill&gt;</code></td><td><code>emakiskills.admin</code></td><td>Get a player&#39;s skill level.</td></tr><tr><td><code>/eskills level set &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>Set a player&#39;s skill level.</td></tr><tr><td><code>/eskills level add &lt;player&gt; &lt;skill&gt; &lt;value&gt;</code></td><td><code>emakiskills.admin</code></td><td>Add levels to a player&#39;s skill.</td></tr><tr><td><code>/eskills clearslot &lt;player&gt; &lt;slot&gt;</code></td><td><code>emakiskills.admin</code></td><td>Clear a player&#39;s skill slot binding.</td></tr><tr><td><code>/eskills inspect [player]</code></td><td><code>emakiskills.use</code> or <code>emakiskills.admin</code></td><td>Inspect whether the player profile is loaded and how slots 0-8 are bound.</td></tr><tr><td><code>/eskills resync [player]</code></td><td><code>emakiskills.admin</code></td><td>Validate and resync the player&#39;s skill slot bindings.</td></tr><tr><td>\`/eskills debug &lt;status</td><td>player</td><td>module</td></tr><tr><td><code>/eskills reload</code></td><td><code>emakiskills.reload</code> or <code>emakiskills.admin</code></td><td>Reload skills, resources, GUI, language, and main configuration.</td></tr></tbody></table><p>Use <code>/eskills gui</code> to open the interface. Trigger bindings are handled through the GUI.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakiskills.use</code></td><td>true</td><td>Allows basic skill usage, GUI access, cast mode switching, skill upgrades, and profile inspection.</td></tr><tr><td><code>emakiskills.reload</code></td><td>op</td><td>Allows reloading configuration.</td></tr><tr><td><code>emakiskills.admin</code></td><td>op</td><td>Allows level management, slot clearing, resync, and acts as an administrative fallback for basic features.</td></tr><tr><td><code>emakiskills.debug</code></td><td>op</td><td>Allows debug output.</td></tr></tbody></table><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to &quot;Common operations&quot;">​</a></h2><h3 id="cast-mode" tabindex="-1">Cast mode <a class="header-anchor" href="#cast-mode" aria-label="Permalink to &quot;Cast mode&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/eskills castmode toggle</span></span>
<span class="line"><span>/eskills castmode on</span></span>
<span class="line"><span>/eskills castmode off</span></span></code></pre></div><p>Cast mode affects active skill triggering. Whether the previous state is restored on join depends on <code>cast_mode.restore_last_state_on_join</code>.</p><h3 id="manage-skill-levels" tabindex="-1">Manage skill levels <a class="header-anchor" href="#manage-skill-levels" aria-label="Permalink to &quot;Manage skill levels&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/eskills level get Steve fireball</span></span>
<span class="line"><span>/eskills level set Steve fireball 3</span></span>
<span class="line"><span>/eskills level add Steve fireball 1</span></span></code></pre></div><p>Level changes affect skill parameters, resource costs, script variables, and upgrade checks.</p><h3 id="clear-a-slot-and-resync" tabindex="-1">Clear a slot and resync <a class="header-anchor" href="#clear-a-slot-and-resync" aria-label="Permalink to &quot;Clear a slot and resync&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/eskills clearslot Steve 1</span></span>
<span class="line"><span>/eskills resync Steve</span></span></code></pre></div><p>Use these after deleting skills, changing equipment-provided skills, or fixing invalid slot bindings.</p>`,16)])])}const h=s(d,[["render",i]]);export{k as __pageData,h as default};
